def rref(rows):
 piv={}
 for row in rows:
  while row:
   i=row.bit_length()-1
   if i in piv:row^=piv[i]
   else:piv[i]=row;break
 return piv

def nullbasis(rows,n):
 piv=rref(rows);basis=[]
 for j in range(n):
  if j in piv:continue
  v=1<<j
  for i in sorted(piv):
   if (v&piv[i]).bit_count()%2:v^=1<<i
  basis.append(v)
 return basis,list(piv.values())

